with recent_departments as (select * from departments where dept_name in ('Marketing', 'Finance')), agg as (select case when budget >= 3091000 then 'high' when budget >= 1954000 then 'mid' else 'low' end as budget_bucket, sort_array(collect_set(dept_name)) as dept_name_list from recent_departments group by case when budget >= 3091000 then 'high' when budget >= 1954000 then 'mid' else 'low' end) select budget_bucket, dept_name_list from agg;
